using System;using System.Text;using System.Collections.Generic;
// Presentation only: verdicts are never promoted to source facts or owner approval.
public static class SourceProposalPresentation {
 public static string SavedAtomicChecks(object value){var b=new StringBuilder();var state=ManualHypotheses.D(value);foreach(var wrap in ManualHypotheses.A(ManualHypotheses.V(state,"entries"))){var row=LocalJson.ParseObject(ManualHypotheses.S(ManualHypotheses.D(wrap),"payload_json"));b.Append(AtomicChecks(ManualHypotheses.V(row,"result")));}return b.ToString();}
 public static string AtomicChecks(object value){var result=ManualHypotheses.D(value);var checks=ManualHypotheses.D(ManualHypotheses.V(result,"atom_checks"));if(checks.Count==0)return "";var b=new StringBuilder("SOURCE-BOUND PROPOSITION CHECKS / UNVERIFIED MODEL VERDICTS\r\nNot verified facts, explanations, fixes or approval. Compare the reason and exact input citations.\r\n");foreach(var pair in checks){var row=ManualHypotheses.D(pair.Value);b.AppendLine("Proposition: "+pair.Key+" | "+ManualHypotheses.S(row,"verdict"));b.AppendLine("Untrusted proposition: "+ManualHypotheses.S(row,"statement"));b.AppendLine("Source: "+ManualHypotheses.S(row,"source_id")+" | field: "+ManualHypotheses.S(row,"field_id"));b.AppendLine("Unverified reason: "+ManualHypotheses.S(row,"reason"));foreach(var item in ManualHypotheses.A(ManualHypotheses.V(row,"citations"))){var c=ManualHypotheses.D(item);b.AppendLine("Input unit "+ManualHypotheses.S(c,"unit_id")+" ["+ManualHypotheses.S(c,"start")+","+ManualHypotheses.S(c,"end")+"): "+ManualHypotheses.S(c,"quote"));}}return b.ToString();}
}
